import { ConfigProvider, Layout } from '@arco-design/web-react';
import enUS from '@arco-design/web-react/es/locale/en-US';
import Header from './component/header';
import { MainForm } from './component/mainForm';
import './App.css';
import '@arco-design/web-react/dist/css/arco.css';
import { BrowserRouter, Route, Routes } from 'react-router';
import Dashboard from './component/dashboard';
import LoginPage from './component/loginPage';


function App() {
  console.log('PUBLIC_URL', process.env.PUBLIC_URL);

  const baseRoute = process.env.PUBLIC_URL ? new URL(process.env.PUBLIC_URL).pathname : undefined;
  console.log('App baseRoute', baseRoute, process.env.PUBLIC_URL);

  return (
    <ConfigProvider locale={enUS}>
      <BrowserRouter basename={baseRoute}>
        <div className="App">
          <Layout>
            <Layout.Header>
              <Header />
            </Layout.Header>
            <Layout.Content>
              <Routes>
                <Route path='/' element={<MainForm />} />
                <Route path='/experiment/:expId?/edit' element={<MainForm />} />
                <Route path='/my' element={<Dashboard />} />
                <Route path='/login' element={<LoginPage />} />
              </Routes>
            </Layout.Content>
          </Layout>
        </div>
      </BrowserRouter>
    </ConfigProvider>
  );
}

export default App;
